package com.nextaicommerce.platform.orders;
import com.nextaicommerce.platform.catalog.CatalogRepository;import com.nextaicommerce.platform.web.WorkspaceAccessRepository;import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.ui.ExtendedModelMap;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class OrdersCatalogueEntryTest {
 @Test void sharedAddDialogReceivesCurrentAccountVendorChoices(){var catalog=mock(CatalogRepository.class);var orders=mock(OrderRepository.class,RETURNS_DEEP_STUBS);var workspace=mock(WorkspaceAccessRepository.class);var sync=mock(com.nextaicommerce.platform.sync.AmazonManualOrderSync.class,RETURNS_DEEP_STUBS);var controller=new OrderController(orders,workspace,sync,null);
 ReflectionTestUtils.setField(controller,"fba",mock(com.nextaicommerce.platform.fba.FbaReadRepository.class));ReflectionTestUtils.setField(controller,"refundHistory",mock(SkuRefundHistory.class));ReflectionTestUtils.setField(controller,"catalog",catalog);UUID tenant=UUID.randomUUID();var session=new MockHttpSession();session.setAttribute("selectedTenantId",tenant);session.setAttribute("selectedTenantName","Own account");UUID connection=UUID.randomUUID();session.setAttribute(com.nextaicommerce.platform.web.AccountSelectionController.STORE_ID,connection);when(workspace.findConnection(tenant,connection)).thenReturn(new WorkspaceAccessRepository.ConnectionIdentity(connection,"AMAZON"));
 when(orders.orders(eq(tenant),eq(connection),eq("ALL"),eq(""),eq(0),eq(25),anyMap())).thenReturn(new OrderRepository.OrderPage(List.of(),0,0,25));
 when(orders.summary(tenant,connection)).thenReturn(new OrderRepository.OrderSummary(0,BigDecimal.ZERO,BigDecimal.ZERO,0,0,null,0));
 when(sync.availability(tenant,connection)).thenReturn(new com.nextaicommerce.platform.sync.AmazonManualOrderSync.Availability(false,null,null,null));var vendor=new CatalogRepository.VendorView(UUID.randomUUID(),"Own vendor","OWN","USD",BigDecimal.ZERO,BigDecimal.ZERO,0,"ACTIVE");when(catalog.listVendorChoices(tenant)).thenReturn(List.of(vendor));var model=new ExtendedModelMap();var auth=UsernamePasswordAuthenticationToken.authenticated("owner@example.invalid","unused",List.of(new SimpleGrantedAuthority("ROLE_OWNER")));assertThat(controller.orders("ALL","",0,null,25,auth,session,model,Map.of())).isEqualTo("orders");assertThat(model.get("vendors")).isEqualTo(List.of(vendor));verify(catalog).listVendorChoices(tenant);}
}
